// Software contract exercise of the shipped consumer against actual Go
// BrowserSSO.Account output. Inputs are ephemeral test authority only.
let raw='';for await(const chunk of process.stdin)raw+=chunk;if(raw.length>65536)throw Error('Bounded ephemeral input required');const input=JSON.parse(raw);
const {createMediaBrowserIdentity}=await import(new URL('../../../apps/'+(input.productId==='video'?'video':'creator-studio')+'/browser-identity.js',import.meta.url));
let proofCalls=0;const identity=createMediaBrowserIdentity({productId:input.productId,environment:{location:{origin:input.session.origin},fetch:async(url,options)=>{if(url!==input.session.origin+'/api/sso/account'||options.credentials!=='same-origin'||options.redirect!=='error')throw Error('Original Host contract required');return new Response(input.accountBody,{status:200,headers:input.accountHeaders})}}});
try{const headers=await identity.authorization(input.session,async()=>{proofCalls++;return input.headers});if(proofCalls!==1||headers['X-YNX-SSO-CSRF']!==input.expectedCSRF)throw Error('Original browser and private authority required');let wrongRejected=false;try{await identity.authorization({...input.session,account:input.session.account+'-wrong'},async()=>{proofCalls++;return input.headers})}catch{wrongRejected=true}if(!wrongRejected||proofCalls!==1)throw Error('Cross-account proof was attempted');process.stdout.write(JSON.stringify(headers));}finally{identity.invalidate()}
